 "content": "def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def edge_runs(horizontal, fixed):
        n = w if horizontal else h
        result = []
        i = 0
        while i < n:
            r, c = (fixed, i) if horizontal else (i, fixed)
            color = grid[r][c]
            if color == bg:
                i += 1
                continue
            j = i + 1
            while j < n:
                rr, cc = (fixed, j) if horizontal else (j, fixed)
                if grid[rr][cc] != color:
                    break
                j += 1
            result.append((i, j, color))
            i = j
        return result

    # Pair equal-length, same-color bars on opposing edges. Interior marks
    # select offsets in the paired bars; rays project inward from both bars.
    for horizontal in (True, False):
        if horizontal:
            edge0, edge1 = 0, h - 1
            runs0, runs1 = edge_runs(True, edge0), edge_runs(True, edge1)
        else:
            edge0, edge1 = 0, w - 1
            runs0, runs1 = edge_runs(False, edge0), edge_runs(False, edge1)

        for a0, a1, acolor in runs0:
            for b0, b1, bcolor in runs1:
                if acolor != bcolor or a1 - a0 != b1 - b0:
                    continue
                length = a1 - a0
                selected = {}
                # A mark selects its offset from whichever opposing bar span contains it.
                for r in range(1, h - 1):
                    for c in range(1, w - 1):
                        value = grid[r][c]
                        if value == bg:
                            continue
                        pos = c if horizontal else r
                        if a0 <= pos < a1:
                            selected[pos - a0] = (value, r, c, 0)
                        elif b0 <= pos < b1:
                            selected[pos - b0] = (value, r, c, 1)

                for offset, (value, mr, mc, mark_side) in selected.items():
                    pos0, pos1 = a0 + offset, b0 + offset
                    # From the marked boundary side, fill up to the mark and convert it to 4.
                    source_edge = edge0 if mark_side == 0 else edge1
                    pos = pos0 if mark_side == 0 else pos1
                    if horizontal:
                        step = 1 if source_edge == 0 else -1
                        rr = source_edge + step
                        while 0 <= rr < h:
                            if rr == mr and pos == mc:
                                out[rr][pos] = 4
                                break
                            if grid[rr][pos] != bg:
                                out[rr][pos] = 4
                                break
                            out[rr][pos] = value
                            rr += step
                    else:
                        step = 1 if source_edge == 0 else -1
                        cc = source_edge + step
                        while 0 <= cc < w:
                            if cc == mc and pos == mr:
                                out[pos][cc] = 4
                                break
                            if grid[pos][cc] != bg:
                                out[pos][cc] = 4
                                break
                            out[pos][cc] = value
                            cc += step

                    # Opposing boundary emits the matched offset through the full interior.
                    other_edge = edge1 if mark_side == 0 else edge0
                    other_pos = pos1 if mark_side == 0 else pos0
                    if horizontal:
                        step = -1 if other_edge == h - 1 else 1
                        rr = other_edge + step
                        while 0 <= rr < h:
                            if grid[rr][other_pos] != bg:
                                out[rr][other_pos] = 4
                                break
                            out[rr][other_pos] = value
                            rr += step
                    else:
                        step = -1 if other_edge == w - 1 else 1
                        cc = other_edge + step
                        while 0 <= cc < w:
                            if grid[other_pos][cc] != bg:
                                out[other_pos][cc] = 4
                                break
                            out[other_pos][cc] = value
                            cc += step
    return out
